/**
 * Scenario Persistence Service — Olumi Scenario Schema v2.0
 *
 * Pure async functions wrapping Supabase RPCs and direct queries.
 * No React dependencies. Nothing else in the app calls Supabase
 * for scenario data directly — all access goes through this module.
 *
 * Every function checks `.error` on the Supabase response and throws
 * a typed `ScenarioPersistenceError`. Errors are never swallowed.
 *
 * `eventId` parameters are generated by the **caller** via
 * `crypto.randomUUID()`, never inside service functions. This keeps
 * idempotency control with the caller.
 */

import { supabase } from '../lib/supabase'
import { clearSuppressedScenarioId } from './threadService'
import type {
  ScenarioRow,
  ScenarioListItem,
  ScenarioStage,
  SharedBriefRow,
} from '../types/scenario'
import { ScenarioPersistenceError } from '../types/scenario'

// ---------------------------------------------------------------------------
// Guard: reject non-UUID user IDs (prevents FK violations in guest mode)
// ---------------------------------------------------------------------------

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i

function assertValidUserId(userId: string): void {
  if (!UUID_RE.test(userId)) {
    throw new ScenarioPersistenceError(
      'Supabase persistence requires an authenticated user',
      'INVALID_USER_ID',
    )
  }
}

// ---------------------------------------------------------------------------
// 1. createScenario
// ---------------------------------------------------------------------------

export async function createScenario(
  userId: string,
  eventId: string,
  title?: string,
): Promise<ScenarioRow> {
  assertValidUserId(userId)

  const { data, error } = await supabase
    .from('scenarios')
    .insert({
      user_id: userId,
      title: title ?? null,
      stage: 'frame',
      analysis_status: 'none',
    })
    .select()
    .single()

  if (error) {
    throw new ScenarioPersistenceError(
      `Failed to create scenario: ${error.message}`,
      'CREATE_FAILED',
      error,
    )
  }

  // Append scenario_created event
  const { error: eventError } = await supabase.rpc('append_scenario_event', {
    p_scenario_id: data.id,
    p_event_id: eventId,
    p_event_type: 'scenario_created',
    p_details: {},
    p_hashes: null,
    p_turn_id: null,
  })

  if (eventError) {
    throw new ScenarioPersistenceError(
      `Failed to log scenario_created event: ${eventError.message}`,
      'EVENT_APPEND_FAILED',
      eventError,
    )
  }

  // Clear turn insert suppression so conversation turns can persist for this scenario
  clearSuppressedScenarioId(data.id)

  return data as ScenarioRow
}

// ---------------------------------------------------------------------------
// 2. listScenarios
// ---------------------------------------------------------------------------

export async function listScenarios(
  userId: string,
): Promise<ScenarioListItem[]> {
  assertValidUserId(userId)

  const { data, error } = await supabase
    .from('scenarios')
    .select('id, title, stage, analysis_status, updated_at, created_at, events, is_pinned, is_archived')
    .eq('user_id', userId)
    .order('is_pinned', { ascending: false })
    .order('updated_at', { ascending: false })

  if (error) {
    throw new ScenarioPersistenceError(
      `Failed to list scenarios: ${error.message}`,
      'LIST_FAILED',
      error,
    )
  }

  return (data ?? []) as ScenarioListItem[]
}

// ---------------------------------------------------------------------------
// 3. loadScenario
// ---------------------------------------------------------------------------

export async function loadScenario(
  scenarioId: string,
): Promise<ScenarioRow | null> {
  const { data, error } = await supabase
    .from('scenarios')
    .select('*')
    .eq('id', scenarioId)
    .single()

  if (error) {
    // PGRST116 = "no rows returned" — not found, not an error
    if (error.code === 'PGRST116') return null
    throw new ScenarioPersistenceError(
      `Failed to load scenario: ${error.message}`,
      'LOAD_FAILED',
      error,
    )
  }

  return data as ScenarioRow
}

