// ---------------------------------------------------------------------------
// 7. storeAnalysis (store_analysis_and_log RPC — §4.3)
// ---------------------------------------------------------------------------

export async function storeAnalysis(
  scenarioId: string,
  analysis: unknown,
  graphHash: string,
  /**
   * T2b: null when the engine did not echo a usable seed. The RPC param
   * `p_seed_used INTEGER` has no NOT NULL and no default, and
   * `analysis_provenance` is JSONB, so a null lands as JSON `null` — an
   * honest "unknown" that hydrateAnalysis reads back as null.
   */
  seedUsed: number | null,
  responseHash: string,
  eventId: string,
  details?: Record<string, unknown>,
  turnId?: string,
): Promise<void> {
  const { error } = await supabase.rpc('store_analysis_and_log', {
    p_scenario_id: scenarioId,
    p_analysis: analysis,
    p_graph_hash: graphHash,
    p_seed_used: seedUsed,
    p_response_hash: responseHash,
    p_event_id: eventId,
    p_details: details ?? {},
    p_turn_id: turnId ?? null,
  })

  if (error) {
    throw new ScenarioPersistenceError(
      `Failed to store analysis: ${error.message}`,
      'STORE_ANALYSIS_FAILED',
      error,
    )
  }
}

